INSERT INTO `tours` (`id`, `title`, `slug`, `description`, `highlights`, `included`, `excluded`, `itinerary`, `pricing`, `images`, `dates`, `availability`, `category_id`, `location`, `duration`, `rating`, `view_count`, `created_at`, `updated_at`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `robots_meta`, `og_title`, `og_description`, `og_image`, `twitter_title`, `twitter_description`, `twitter_image`, `schema_markup`, `internal_items`, `included_points`, `excluded_points`, `faq`, `show_price`, `schemas`) VALUES
(18, 'From Delhi: 2 Days Agra and Jaipur Tour By Car', 'from-delhi-2-days-agra-and-jaipur-tour-by-car', '<p><strong>Agra and Jaipur Tour&nbsp;</strong></p><p><strong><span class=\"ql-cursor\">﻿</span></strong>Experience the best of North India with a 2 Days Agra and Jaipur Tour from Delhi by Car. This short Golden Triangle trip lets you explore the majestic Taj Mahal, historic Agra Fort, and the royal charm of Jaipur including Amber Fort and Hawa Mahal. Travel comfortably by private car with a professional driver and expert guide. Perfect for travelers with limited time who want to discover India’s iconic heritage sites in just two days.&nbsp;</p>', '[\"Sunrise visit to the iconic Taj Mahal with expert guide\",\"Explore a grand Agra Fort, a UNESCO World Heritage site\",\"Luxury & Comfortable Delhi\\u2013Agra\\u2013Jaipur journey by private AC car\",\"Explore the magnificent Amer Fort Amber Fort with stunning hill views\",\"Photo stop at the famous Hawa Mahal Palace of Winds\",\"Experience two historic cities in just 2 days from New Delh\"]', '[\"Pickup and drop-off from hotel in New Delhi\",\"Accommodation selected hotel with breakfast.\",\"Private air-conditioned car with professional driver\",\"Private Sightseeing in Agra and Jaipur\",\"Live tour guide service in Agra and Jaipur\"]', '[\"Monument entrance fees\",\"Meals and personal expenses\",\"Tips \\/ gratuities for guide and driver\"]', '[{\"title\":\"Day 1: Delhi Pickup \\u2013 Agra Sightseeing \\u2013 Jaipur\",\"points\":[\"Your journey begins with a pick-up from your hotel in New Delhi or from the airport in a private, air-conditioned car. Subsequently, we will depart for Agra via the Yamuna Expressway, where we will meet your tour guide and visit the world-famous Taj Mahal (a UNESCO World Heritage Site). Afterward, you will have some free time to have lunch or shop in the local markets, as well as to explore the Agra Fort. Upon completing your tour of Agra, we will continue our journey toward Jaipur (also known as the \'Pink City\'). Upon reaching Jaipur, you will check in to your hotel for an overnight stay!\"]},{\"title\":\"Day 2: Jaipur Sightseeing \\u2013 Delhi Drop\",\"points\":[\"After breakfast, start your sightseeing tour of Jaipur with a visit to the magnificent Amber Fort, located on a scenic hilltop and known for its beautiful architecture. Continue to the stunning Hawa Mahal, also called the Palace of Winds, for photos. You may also visit Jaipur\'s City Palace and the historic Jantar Mantar. After completing your Jaipur sightseeing, begin the drive back to New Delhi. On arrival Delhi, you will be dropped at your hotel or preferred location, marking the end of your 2 Days Agra and Jaipur Tour From Delhi.\"]}]', 9999.00, '[\"tours-image\\/cropped_1767538320858_sunrise-taj-2.webp\",\"tours-image\\/cropped_1767538358273_agra-tour-1.webp\",\"tours-image\\/cropped_1767538419287_udaipur-tour.webp\",\"tours-image\\/cropped_1767538451873_varanashi-tour.webp\",\"tours-image\\/cropped_1767538716104_delhi-food-taste.webp\"]', NULL, 20, 1, 'Delhi – Agra – Jaipur', '2 Days', 5.00, 68, '2026-01-04 14:49:45', '2026-04-29 20:31:01', '2 Days Agra & Jaipur Tour from Delhi | Taj Mahal to Jaipur', 'Enjoy the best 2 days Agra Jaipur tour from Delhi. Visit Taj Mahal, Agra Fort,\r\nJal Mahal & City Palace with private car, stays, guide & smooth travel. Book tod', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '[{\"id\":\"0\",\"type\":\"custom\",\"data\":{\"@context\":\"https://schema.org\",\"@type\":\"TouristTrip\"}}]', NULL, NULL, NULL, '[{\"question\":\"1. What is included in the 2 Days Agra & Jaipur Tour from Delhi?\",\"answer\":\"This tour includes private AC transport, hotel accommodation, professional guide, and\\nsightseeing of major attractions like Taj Mahal, Agra Fort, and Jaipur highlights.\"},{\"question\":\"2. Is the Taj Mahal visit included in this tour?\",\"answer\":\"Yes, the tour covers a visit to the iconic Taj Mahal, one of the Seven Wonders of the World, with\\na knowledgeable local guide for a better experience.\"},{\"question\":\"3. How far are Agra and Jaipur from Delhi?\",\"answer\":\"Agra is around 230 km from Delhi, while Jaipur is about 280 km. The journey is comfortable via\\nexpressways and highways.\"},{\"question\":\"4. What are the main attractions covered in Jaipur?\",\"answer\":\"In Jaipur, you will explore famous sites like Amber Fort, Hawa Mahal, and City Palace Jaipur.\"},{\"question\":\"5. Is this tour suitable for a short weekend trip?\",\"answer\":\"Absolutely! This 2-day tour is perfect for a quick getaway from Delhi, covering top highlights of\\nAgra and Jaipur in a time-efficient and comfortable way\"}]', 1, '[{\"id\":\"0\",\"type\":\"custom\",\"data\":{\"@context\":\"https://schema.org\",\"@type\":\"TouristTrip\"}}]'),
(40, 'Taj Mahal Sunrise Tour From Delhi', 'taj-mahal-sunrise-tour-from-delhi', '<p><strong>Sunrise Taj Mahal &amp; Agra Trip</strong></p><p><strong>﻿</strong>One of the best same-day trips to the Taj Mahal is the Taj Mahal Sunrise Tour from Delhi. Start early from Delhi and enjoy a peaceful visit with fewer crowds and stunning sunrise views. For a smooth trip, ride in a private air-conditioned car with an expert guide and skip the queue. Visit Agra\'s best sights and come back the same day in comfort. Great for couples and people who want to travel without any problems. Reserve now for an unforgettable trip to the Taj Mahal Sunrise Tour From Delhi.&nbsp;</p>', '[\"Sunrise visit to Taj Mahal with expert local guide\",\"Private AC car with hotel pickup & drop from Delhi\",\"Skip-the-line entry for smooth, hassle-free tour\",\"Explore Agra Fort & local markets with guide\",\"Luxury hotel stay with breakfast (if selected)\",\"Fully private tour with flexible timing & comfort\"]', '[\"Private air-conditioned vehicle for full-day tour\",\"Hotel pickup & drop-off in Delhi \\/ NCR\",\"Professional English-speaking tour guide in Agra\",\"Skip-the-line entry tickets to Taj Mahal\",\"Monuments Entrance Fees\",\"Visit to Agra Fort & local sightseeing\",\"Bottled water during the journey\",\"All toll taxes, parking fees & driver allowance\"]', '[\"Lunch or dinner\",\"Personal expenses\",\"Tips\"]', '[{\"title\":\"02:30 AM \\u2013 Pickup from Delhi NCR\",\"points\":[\"Your driver will pick you up at your hotel, the airport, or any other place you choose in Delhi NCR. Start your comfortable trip in a private car with air conditioning so you can relax and enjoy the ride.\"]},{\"title\":\"03:00 AM \\u2013 Drive to Agra via Yamuna Expressway\",\"points\":[\"The Yamuna Motorway is one of India\'s best highways, so you can enjoy a quiet drive. The trip takes about three to four hours, and there are beautiful views along the way.\"]},{\"title\":\"05:45 AM \\u2013 Arrival in Agra & Meet Tour Guide\",\"points\":[\"When you get to Agra, you\'ll meet your professional local tour guide, who will help you with the sightseeing.\"]},{\"title\":\"06:00 AM \\u2013 Visit to Taj Mahal at Sunrise\",\"points\":[\"At Sunrise, the Taj Mahal glows in golden hues, making it a magical place to be. Take a guided tour, learn about its romantic past and architecture, and take beautiful pictures without a lot of people around.\"]},{\"title\":\"08:30 AM \\u2013 Breakfast at 5-Star Hotel\",\"points\":[\"Take it easy and enjoy a great breakfast at a fancy hotel in Agra (only available in some packages).\"]},{\"title\":\"09:30 AM\\u2014Go to Agra Fort\",\"points\":[\"Visit the UNESCO-listed Agra Fort, a huge Mughal fortress made of red sandstone, and learn about its long history and the lives of the royals who lived there.\"]},{\"title\":\"11:00 AM \\u2013 Local Market & Art Exploration\",\"points\":[\"Go to local markets to see traditional marble inlay work, handicrafts, and souvenirs that are only found in Agra.\"]},{\"title\":\"12:00 PM\\u2014Drive back to Delhi\",\"points\":[\"After seeing the sights, start your comfortable trip back to Delhi with fond memories of your trip.\"]},{\"title\":\"03:30 PM\\u2014Drop-off in Delhi \\/ NCR\",\"points\":[\"You will be dropped off at your hotel, the airport, or wherever you want to go when you get back to Delhi. This marks the end of your amazing Taj Mahal Sunrise Tour.\"]}]', 5999.00, '[\"1777536810_69f30f2aa190d.webp\",\"1777536824_69f30f38d4f40.webp\",\"1777536832_69f30f408a47d.webp\",\"1777536894_69f30f7e5ae01.webp\",\"1777536894_69f30f7e5affe.webp\",\"1777536894_69f30f7e5b491.webp\",\"1777536894_69f30f7e5b56c.jpg\",\"1777536894_69f30f7e5b6a0.webp\",\"1777536894_69f30f7e5b939.webp\"]', NULL, 20, 2, 'Delhi – Agra – Delhi', '1 Day', 5.00, 29, '2026-01-04 18:06:08', '2026-04-30 08:15:03', 'Taj Mahal Sunrise Tour from Delhi | Private Guide & AC Car', 'See the Taj Mahal at sunrise on a private tour from Delhi. Enjoy\r\nthe Agra Monuments with AC car, expert guide & skip-the-line entry. Limited\r\nslots—book now!', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[{\"question\":\"1. What is the best time to visit the Taj Mahal for sunrise?\",\"answer\":\"The best time to visit the Taj Mahal is at sunrise, usually between 5:30 AM to 6:30 AM\\ndepending on the season. Early morning offers fewer crowds, soft golden light, and the most\\npeaceful experience for photography and sightseeing.\"},{\"question\":\"2. How far is the Taj Mahal from Delhi and how long does it take?\",\"answer\":\"The Taj Mahal is about 230 km from Delhi. It takes around 3 to 4 hours by car via the\\nYamuna Expressway, making it ideal for a same-day sunrise tour.\"},{\"question\":\"3. Is the Taj Mahal Sunrise Tour from Delhi worth it?\",\"answer\":\"Yes, the Taj Mahal Sunrise Tour is highly recommended. You avoid heavy crowds, enjoy\\ncooler weather, and witness the monument glowing beautifully in the early morning\\nlight\\u2014perfect for a memorable experience.\"},{\"question\":\"4. What is included in a Taj Mahal Sunrise Tour package?\",\"answer\":\"Most tours include private AC transport, hotel pickup & drop-off, an experienced guide,\\nskip-the-line entry tickets, and breakfast at a 4 or 5-star hotel in Agra.\"},{\"question\":\"5. What should I carry for the Taj Mahal Sunrise Tour?\",\"answer\":\"Carry a valid ID, comfortable walking shoes, sunglasses, a camera, and light clothing. In\\nwinter, bring a jacket as mornings can be chilly in Agra.\"}]', 1, ''),
(41, 'From Delhi: Taj Mahal And Agra Overnight Tour', 'from-delhi-taj-mahal-and-agra-overnight-tour', '<p>This overnight Agra tour from Delhi allows travelers to explore the city at a relaxed pace without rushing through major attractions. Starting from Delhi, the journey takes you to Agra where you visit the Taj Mahal, Agra Fort, and local markets. An overnight stay in <a href=\"https://en.wikipedia.org/wiki/Agra\" rel=\"noopener noreferrer\" target=\"_blank\">Agra</a> gives you time to enjoy the city’s heritage, cuisine, and atmosphere beyond a single day. The tour is well-suited for couples and families who prefer comfortable travel with private transportation and flexible sightseeing. With experienced drivers and optional guided tours, this package ensures a smooth and enriching travel experience. The overnight stay also allows you to avoid long same-day travel fatigue while enjoying Agra’s Mughal charm. This <a href=\"https://indiadaytrip.com/tour/from-delhi-taj-mahal-and-agra-overnight-tour\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>From Delhi: Taj Mahal And Agra Overnight Tour</strong></a> combines convenience, comfort, and cultural depth, making it a popular choice for short North India getaways.</p>', '[\"Visit Taj Mahal and Agra Fort\",\"Overnight stay in Agra\",\"Private car from Delhi\",\"Local market exploration\",\"Relaxed sightseeing schedule\"]', '[\"Private AC vehicle\",\"Hotel accommodation\",\"Driver allowance\",\"Sightseeing as per plan\",\"All road taxes\"]', '[\"Monument entry fees\",\"Meals unless specified\",\"Personal expenses\",\"Camera charges\",\"Insurance\"]', '[{\"title\":\"Day 1\",\"points\":[\"Delhi to Agra sightseeing\"]},{\"title\":\"Day 2\",\"points\":[\"Optional sunrise visit and return to Delhi\"]}]', 7999.00, '[\"tours-image\\/cropped_1767810298767_cropped_1766848989644_udaipur-tour.webp\",\"tours-image\\/cropped_1766849017264_udaipur-tour.webp\",\"tours-image\\/cropped_1766849235504_amritsar-tour.webp\",\"tours-image\\/cropped_1766849432245_amritsar-tour.webp\",\"tours-image\\/cropped_1766849852474_night-taj-mahal.webp\"]', NULL, 20, 2, 'Delhi – Agra', '2 Days', 5.00, 42, '2026-01-05 18:56:58', '2026-04-30 09:10:57', 'Agra Overnight Tour from Delhi | Taj Mahal Sunrise & Sunset', 'Fall in love with the Taj Mahal—watch it glow at sunrise and shine at sunset on a magical overnight tour from Delhi. A truly unforgettable experience!', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(42, 'Taj Mahal Sunrise And Old Delhi Tour', 'taj-mahal-sunrise-and-old-delhi-tour', '<p>The <a href=\"https://indiadaytrip.com/tour/taj-mahal-sunrise-and-old-delhi-tour\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Taj Mahal Sunrise and Old Delhi Tour</strong></a> combines two iconic experiences in one memorable journey. Begin early with a sunrise visit to the Taj Mahal in Agra, where the soft morning light enhances the monument’s beauty and calm atmosphere. After exploring Agra Fort, return to Delhi to discover the vibrant charm of Old Delhi. This part of the tour includes narrow lanes, historic mosques, bustling markets, and traditional street life. The contrast between Mughal elegance and <a href=\"https://en.wikipedia.org/wiki/Delhi\" rel=\"noopener noreferrer\" target=\"_blank\">Delhi</a> lively heritage offers a complete cultural experience in a single day. Designed for travelers who want both monument sightseeing and authentic local exploration, the tour includes private transport and expert guidance. It is ideal for visitors interested in history, photography, and traditional Indian culture, all within a well-managed and time-efficient itinerary.</p>', '[\"Sunrise Taj Mahal visit\",\"Agra Fort exploration\",\"Old Delhi heritage walk\",\"Private AC transportation\",\"Cultural and historical contrast\"]', '[\"Private car with driver\",\"Local guide services\",\"Sightseeing as per itinerary\",\"Fuel and toll taxes\",\"All parking charges\"]', '[\"Monument entrance fees\",\"Meals\",\"Personal expenses\",\"Camera charges\",\"Tips\"]', '[{\"title\":\"Day 1\",\"points\":[\"Early departure from Delhi\",\"Sunrise Taj Mahal and Agra Fort\",\"Return to Delhi\",\"Old Delhi sightseeing\"]}]', 6999.00, '[\"tours-image\\/cropped_1767810330464_cropped_1767538320858_sunrise-taj-2.webp\",\"tours-image\\/cropped_1767538358273_agra-tour-1.webp\",\"tours-image\\/cropped_1767538419287_udaipur-tour.webp\",\"tours-image\\/cropped_1767538451873_varanashi-tour.webp\",\"tours-image\\/cropped_1767538716104_delhi-food-taste.webp\"]', NULL, 20, 1, 'Delhi – Agra', '1 Day', 5.00, 22, '2026-01-05 19:02:23', '2026-04-28 08:22:37', 'Taj Mahal Sunrise & Old Delhi Tour | One Day Tour from Delhi', 'Watch the Taj Mahal at sunrise, then explore Old Delhi in one day. Private tour, fast entry, AC car & guide included. Book your unforgettable trip now.', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(43, 'Golden Triangle Tour 4N5D', 'golden-triangle-tour-4n5d', '<p>The <a href=\"https://indiadaytrip.com/tour/golden-triangle-tour-4n5d\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Golden Triangle Tour 4N5D</strong></a> is one of the most popular travel circuits in India, covering Delhi, Agra, and Jaipur. This well-paced itinerary allows travelers to explore historical landmarks, royal palaces, and cultural heritage across North India. Starting in Delhi, the tour moves to Agra to witness the Taj Mahal and Mughal architecture, followed by Jaipur, known for its forts, palaces, and colorful markets. The five-day duration ensures comfortable travel without rushing, making it suitable for families and first-time visitors. With private transportation, guided sightseeing, and quality accommodations, this tour offers a complete introduction to India’s rich history and traditions. The 5 Day Golden Triangle route is ideal for understanding the diversity, architecture, and lifestyle of North India in a structured and enjoyable way.</p>', '[\"Delhi city sightseeing\",\"Taj Mahal and Agra Fort\",\"Jaipur forts and palaces\",\"Private car tour\",\"Balanced travel pace\"]', '[\"Private AC vehicle\",\"Hotel accommodation\",\"Driver allowance\",\"Sightseeing as per plan\",\"All tolls and taxes\"]', '[\"Monument entry tickets\",\"Meals not mentioned\",\"Personal expenses\",\"Camera fees\",\"Insurance\"]', '[{\"title\":\"Day 1\",\"points\":[\"Arrival in Delhi sightseeing\"]},{\"title\":\"Day 2\",\"points\":[\"Delhi to Agra\"]},{\"title\":\"Day 3\",\"points\":[\"Agra to Jaipur\"]},{\"title\":\"Day 4\",\"points\":[\"Jaipur sightseeing\"]},{\"title\":\"Day 5\",\"points\":[\"Departure\"]}]', 18999.00, '[\"tours-image\\/cropped_1766858356515_delhi-food-taste.webp\",\"tours-image\\/cropped_1766858392129_night-delhi.webp\"]', NULL, 20, 3, 'Delhi – Agra – Jaipur', '5 Days', 5.00, 90, '2026-01-05 19:06:45', '2026-04-30 07:55:00', 'Golden Triangle Tour 4N/5D | With Private Car, Hotel & Guide', 'Discover Delhi, Agra & Jaipur on a 4N/5D Golden Triangle Tour. Explore Taj Mahal, Amber Fort & city highlights with private car , stays & guide. Reserve today!', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(44, 'Golden Triangle Tour with Amritsar 6N7D', 'golden-triangle-tour-with-amritsar-6n7d', '<p>The <a href=\"https://indiadaytrip.com/tour/golden-triangle-tour-with-amritsar-6n7d\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Golden Triangle Tour with Amritsar 6N7D</strong></a> extends the classic Delhi, Agra, and Jaipur circuit by adding the spiritual and cultural city of Amritsar. Along with iconic attractions like the Taj Mahal and Jaipur’s royal forts, this tour includes a visit to the <a href=\"https://en.wikipedia.org/wiki/Golden_Temple\" rel=\"noopener noreferrer\" target=\"_blank\">Golden Temple</a>, one of India’s most sacred sites. The itinerary blends history, spirituality, and cultural diversity, offering travelers a deeper understanding of North India. Comfortable travel arrangements, guided sightseeing, and well-planned routes ensure a smooth experience across multiple cities. This tour is ideal for travelers seeking both heritage and spiritual enrichment within a single journey. From Mughal monuments to Sikh traditions, the tour offers a balanced and meaningful travel experience.</p>', '[\"Fast Gatimaan Express train journey\",\"Guided Taj Mahal visit\",\"Agra Fort sightseeing\",\"Same-day return\",\"Comfortable and time-saving travel\"]', '[\"Train tickets\",\"Local AC transport in Agra\",\"Tour guide\",\"Sightseeing as planned\",\"All applicable taxes\"]', '[\"Monument entrance fees\",\"Meals other than train service\",\"Personal expenses\",\"Camera charges\",\"Tips\"]', '[{\"title\":\"Day 1\",\"points\":[\"Morning train from Delhi\",\"Taj Mahal and Agra Fort visit\",\"Evening return by train\"]}]', 6499.00, '[\"tours-image\\/cropped_1767810432484_cropped_1767538320858_sunrise-taj-2.webp\",\"tours-image\\/cropped_1767538358273_agra-tour-1.webp\",\"tours-image\\/cropped_1767538419287_udaipur-tour.webp\",\"tours-image\\/cropped_1767538451873_varanashi-tour.webp\",\"tours-image\\/cropped_1767538716104_delhi-food-taste.webp\"]', NULL, 20, 2, 'Delhi – Agra – Delhi', '1 Day', 5.00, 32, '2026-01-05 19:07:15', '2026-04-28 08:19:03', 'Golden Triangle Tour with Amritsar | With Golden Temple Tour', 'From Golden Temple serenity to Wagah Border energy, explore Delhi, Agra & Jaipur on this Golden Triangle tour with AC car, guide & stays. A journey to remember.', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(45, 'Taj Mahal Tour by Gatimaan Express Train', 'taj-mahal-tour-by-gatimaan-express-train', '<p>The <a href=\"https://indiadaytrip.com/tour/taj-mahal-tour-by-gatimaan-express-train\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Taj Mahal Tour by Gatimaan Express Train</strong></a> is the fastest and most comfortable way to visit Agra from Delhi. <a href=\"https://en.wikipedia.org/wiki/Gatiman_Express\" rel=\"noopener noreferrer\" target=\"_blank\">Gatimaan Express</a> offers a smooth and time-efficient rail journey, allowing travelers to maximize sightseeing time in Agra. This tour includes a guided visit to the Taj Mahal and Agra Fort, making it ideal for travelers who prefer train travel over long road journeys. With early morning departure and same-day return, the tour is perfect for business travelers, families, and senior citizens. The combination of modern train facilities and well-organized local transfers ensures a hassle-free experience. This tour provides a convenient, reliable, and comfortable option to explore Agra’s iconic monuments in one day.</p>', '[\"Fast Gatimaan Express train journey\",\"Guided Taj Mahal visit\",\"Agra Fort sightseeing\",\"Same-day return\",\"Comfortable and time-saving travel\"]', '[\"Train tickets\",\"Local AC transport in Agra\",\"Tour guide\",\"Sightseeing as planned\",\"All applicable taxes\"]', '[\"Monument entrance fees\",\"Meals other than train service\",\"Personal expenses\",\"Camera charges\"]', '[{\"title\":\"Day 1\",\"points\":[\"Morning train from Delhi\",\"Taj Mahal and Agra Fort visit\",\"Evening return by train\"]}]', 6499.00, '[\"tours-image\\/cropped_1767810456823_cropped_1766848989644_udaipur-tour.webp\",\"tours-image\\/cropped_1766849017264_udaipur-tour.webp\",\"tours-image\\/cropped_1766849235504_amritsar-tour.webp\",\"tours-image\\/cropped_1766849432245_amritsar-tour.webp\",\"tours-image\\/cropped_1766849852474_night-taj-mahal.webp\"]', NULL, 20, 2, 'Delhi – Agra – Delhi', '1 Day', 5.00, 28, '2026-01-07 17:41:49', '2026-04-28 09:11:40', 'Taj Mahal Tour by Gatimaan Express Train | Fastest Agra Trip', 'Explore the Taj Mahal & Agra by Gatimaan Express train. Day trip from Delhi with guide, AC chair car & skip-the-line access. Secure your spot today!', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(46, 'Golden Triangle Tours with Varanasi 5N6D', 'golden-triangle-tours-with-varanasi-5n6d', '<p>The Golden Triangle Tour with Varanasi combines North India’s most famous heritage cities with one of the world’s oldest living spiritual centers. Along with Delhi, Agra, and Jaipur, this tour includes <a href=\"https://en.wikipedia.org/wiki/Varanasi\" rel=\"noopener noreferrer\" target=\"_blank\">Varanasi</a>, known for its sacred ghats, temples, and spiritual rituals along the Ganges River. The itinerary offers a perfect mix of history, culture, and spirituality. Travelers experience Mughal monuments, Rajput architecture, and deeply rooted religious traditions in one comprehensive journey. Comfortable transportation, guided sightseeing, and well-planned stays ensure a smooth experience. This <a href=\"https://indiadaytrip.com/tour/golden-triangle-tours-with-varanasi-5n6d\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Golden Triangle Tours with Varanasi 5N6D</strong></a> is ideal for travelers seeking both cultural exploration and spiritual insight within a limited timeframe</p>', '[\"Ganga Aarti in Varanasi\",\"Golden Triangle sightseeing\",\"Taj Mahal and Jaipur forts\",\"Cultural and spiritual blend\",\"Private guided travel\"]', '[\"Private AC transport\",\"Hotel accommodation\",\"Driver allowance\",\"Sightseeing as per plan\",\"All taxes\"]', '[\"Monument entry fees\",\"Meals not specified\",\"Personal expenses\",\"Camera charges\",\"Insurance\"]', '[]', 26999.00, '[\"tours-image\\/cropped_1767810522120_cropped_1767538320858_sunrise-taj-2.webp\",\"tours-image\\/cropped_1767538358273_agra-tour-1.webp\",\"tours-image\\/cropped_1767538419287_udaipur-tour.webp\",\"tours-image\\/cropped_1767538451873_varanashi-tour.webp\",\"tours-image\\/cropped_1767810542316_cropped_1766849852474_night-taj-mahal.webp\"]', NULL, 20, 3, 'Delhi – Agra – Jaipur – Varanasi', '6 Days', 5.00, 29, '2026-01-07 17:45:48', '2026-04-28 08:15:54', 'Golden Triangle with Varanasi | Delhi Agra Jaipur & Varanasi', 'From the Taj Mahal to Varanasi’s Ganga Aarti, experience India’s most iconic sights in one unforgettable 5N/6D journey. Culture, heritage & spirituality await!', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(47, 'Taj Mahal and Agra Tour by Premium Cars', 'taj-mahal-and-agra-tour-by-premium-cars', '<p>The Luxury Taj Mahal Tour by Premium Cars is designed for travelers who want an exclusive and high-end travel experience from Delhi to Agra. Enjoy a private journey in top-class vehicles like Mercedes-Benz, BMW, or luxury SUVs with a professional chauffeur and expert guide. Travel smoothly via the Yamuna Expressway while experiencing personalized service and flexible sightseeing. This <a href=\"https://indiadaytrip.com/tour/taj-mahal-and-agra-tour-by-premium-cars\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Taj Mahal and Agra Tour by Premium Cars</strong></a> offers comfort, privacy, and a truly unforgettable <a href=\"https://en.wikipedia.org/wiki/Taj_Mahal\" rel=\"noopener noreferrer\" target=\"_blank\">Taj Mahal</a> luxury travel experience</p>', '[\"Travel in Premium Cars like Mercedes-Benz, BMW, or luxury SUVs\",\"Private chauffeur drive from Delhi to Agra\",\"Guided luxury visit to the iconic Taj Mahal\",\"Explore royal history inside Agra Fort with guide\",\"Visit elegant Tomb of I\'timad-ud-Daulah Baby Taj monument\",\"Personalized luxury tour with flexible schedule & comfort\"]', '[\"Private AC Premium car for Delhi\\u2013Agra\\u2013Delhi travel\",\"Professional English-speaking tour guide in Agra\",\"Pick-up and drop-off from hotel\\/airport in Delhi\",\"All toll taxes, parking fees, and fuel charges\",\"Sightseeing of Taj Mahal and Agra Fort\",\"Bottled mineral water during the journey\"]', '[\"Entrance fees for Taj Mahal and Agra Fort\",\"Meals and personal expenses\",\"Tips for driver and tour guide\"]', '[{\"title\":\"06:00 AM \\u2013 Pickup from Hotel in Delhi\",\"points\":[\"Your private chauffeur will arrive in a magnificent Mercedes-Benz, BMW, or luxury SUV, promising an enjoyable journey to Agra via the Yamuna Expressway. Comfortable seats await you, and you will be provided with refreshing bottled water throughout this truly delightful experience!\"]},{\"title\":\"07:30 AM \\u2013 Scenic Drive on Yamuna Expressway\",\"points\":[\"Enjoy a fun, luxury road trip between Delhi and Agra on one of India\'s finest highways\\u2014traveling in comfort, style, and privacy. It is a fast yet smooth ride, featuring convenient stops along the way for rest and relaxation! Soak in the picturesque rural landscapes as you speed along this Indian highway connecting Delhi and Agra!\"]},{\"title\":\"9:00 AM: Arrival in Agra \\u2013 A Warm Welcome by Your Guide\",\"points\":[\"Arrive in Agra and meet your professional tour guide, who will accompany you throughout your exploration of this historic Mughal city. Begin discovering its rich Mughal heritage at your own pace, enjoying personalized attention within a relaxed and flexible tour itinerary.\"]},{\"title\":\"10:00 AM \\u2013 Visit the Iconic Taj Mahal\",\"points\":[\"Visit the Taj Mahal\\u2014one of the world\'s most magnificent historical sites. Enjoy an exciting and guided luxury experience that includes fascinating historical anecdotes, ample opportunities for photography, and plenty of time to admire its magnificent architecture.\"]},{\"title\":\"12:00 PM \\u2013 Explore the Agra Fort\",\"points\":[\"Step into a grand Mughal fortress filled with royal palaces and courtyards. Here, you will uncover the intriguing history of the Mughal Empire while admiring spectacular views of the Taj Mahal from within the fort\'s walls. Your guide will provide a detailed introduction to this magnificent site before leading you on a comprehensive tour.\"]},{\"title\":\"01:30 PM \\u2013 Lunch Break\",\"points\":[\"11:30 AM: Enjoy a Splendid Lunch Break! Relax at a 5-star restaurant or hotel in Agra, savoring delicious cuisine and enjoying a delightful dining experience before resuming your afternoon sightseeing tour.\"]},{\"title\":\"02:30 PM - Visit the Baby Taj\",\"points\":[\"Explore this magnificent marble structure, renowned for its intricate carvings and serene gardens\\u2014often referred to as Agra\'s \\\"Baby Taj.\\\" At this tranquil historical site, you will experience Agra\'s rich heritage like never before!\"]},{\"title\":\"4:00 PM: Shopping and Cultural Exploration\",\"points\":[\"Shop for world-famous marble carvings, handicrafts, and souvenirs in Agra! To witness traditional craftsmanship with your own eyes and purchase authentic handmade items, visit renowned handicraft workshops.\"]},{\"title\":\"05:00 PM \\u2013 Drive Back to Delhi\",\"points\":[\"After experiencing the magnificent sights and unique highlights of Agra, relax in your premium vehicle during the return journey via the Yamuna Expressway, enjoying a comfortable ride home along this smooth highway.\"]},{\"title\":\"08:00 PM \\u2013 Arrival & Drop in Delhi\",\"points\":[\"Arrive safely in Delhi, where your driver will drop you off directly at your hotel or your preferred location, bringing your unforgettable Taj Mahal experience to a memorable close.\"]}]', 8999.00, '[\"tours-image\\/cropped_1766858356515_delhi-food-taste.webp\",\"tours-image\\/cropped_1766858392129_night-delhi.webp\",\"tours-image\\/cropped_1766859100725_night-taj-mahal.webp\",\"tours-image\\/cropped_1766859130236_gatiman.webp\"]', NULL, 20, 2, 'Delhi – Agra', '1 Day', 5.00, 228, '2026-01-07 17:46:21', '2026-04-30 08:00:23', 'Taj Mahal & Agra Tour by Premium Car | Luxury Taj Mahal Day', 'Travel in a premium car to the Taj Mahal & Agra. Enjoy a luxury day trip with private guide, skip-the-line entry & seamless experience. Book now!', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[{\"question\":\"1. What is included in the Taj Mahal & Agra Tour by Premium Car?\",\"answer\":\"This tour includes a private premium car, professional driver, pickup & drop from Delhi, and\\nsightseeing of Taj Mahal, Agra Fort, and other key attractions. Optional guide services are\\nalso available\"},{\"question\":\"2. How long does the Taj Mahal day trip from Delhi take?\",\"answer\":\"The tour usually takes around 10\\u201312 hours, including travel time via Yamuna Expressway\\nand sightseeing in Agra.\"},{\"question\":\"3. Is the Taj Mahal open every day?\",\"answer\":\"No, Taj Mahal is closed every Friday. It is open from sunrise to sunset on all other days.\"},{\"question\":\"4. Why should I choose a premium car for the Agra tour?\",\"answer\":\"A premium car ensures maximum comfort, air-conditioning, smooth ride quality, and a luxury\\ntravel experience\\u2014ideal for long-distance travel from Delhi to Agra.\"},{\"question\":\"5. What is the best time to visit the Taj Mahal?\",\"answer\":\"The best time to visit the Taj Mahal is early morning at sunrise for fewer crowds and\\nstunning views. October to March is considered the best season.\"}]', 1, ''),
(48, 'Golden Triangle Tour 2N3D', 'golden-triangle-tour-2n3d', '<p>The <a href=\"https://indiadaytrip.com/tour/golden-triangle-tour-2n3d\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Golden Triangle Tour 2N3D</strong></a> is a compact itinerary covering Delhi, Agra, and Jaipur within three days. Designed for travelers with limited time, this tour focuses on key highlights such as the Taj Mahal, Jaipur’s forts, and Delhi’s historic landmarks. The route is efficient and well-organized, ensuring comfortable travel and maximum sightseeing. Ideal for first-time visitors, the tour provides a quick yet meaningful introduction to North India’s cultural heritage. Private transportation, guided sightseeing, and carefully selected stops make this tour convenient and enjoyable. Despite its short duration, the tour captures the essence of the Golden Triangle experience.</p>', '[\"Short Golden Triangle circuit\",\"Taj Mahal visit\",\"Jaipur heritage sightseeing\",\"Private AC car\",\"Time-efficient itinerary\"]', '[\"Private transportation\",\"Hotel accommodation\",\"Driver allowance\",\"Sightseeing as planned\",\"All road taxes\"]', '[\"Monument entry fees\",\"Meals not mentioned\",\"Personal expenses\",\"Camera charges\",\"Insurance\"]', '[{\"title\":\"Day 1\",\"points\":[\" Delhi to Agra\"]}]', 14999.00, '[\"cropped_1766849235504_amritsar-tour.webp\",\"cropped_1766849432245_amritsar-tour.webp\",\"cropped_1766849852474_night-taj-mahal.webp\",\"cropped_1766850086738_night-taj-mahal.webp\",\"1777535524_69f30a24aaa2a.webp\"]', NULL, 20, 3, 'Delhi – Agra – Jaipur', '3 Days', 5.00, 26, '2026-01-07 17:52:50', '2026-04-30 07:52:08', '', '', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, ''),
(49, 'From Delhi: Day Trip to Taj Mahal and Agra Fort by Car', 'from-delhi-day-trip-to-taj-mahal-and-agra-fort-by-car', '<p>Experience Agra on an enjoyable car tour from Delhi, including visits to Taj Mahal and Agra Fort by car. Enjoy this private excursion that offers hassle-free travel between hotels in Delhi, Gurgaon or Noida to these two iconic sites; travel in an air-conditioned vehicle while touring them both - featuring visits to <a href=\"https://en.wikipedia.org/wiki/Taj_Mahal\" rel=\"noopener noreferrer\" target=\"_blank\">Taj Mahal</a> (UNESCO World Heritage Site and symbol of everlasting love) and Agra Fort (Magnificent Mughal palace composed of red sandstone). With expert guides available and flexible schedules this <a href=\"https://indiadaytrip.com/tour/from-delhi-day-trip-to-taj-mahal-and-agra-fort-by-car\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>From Delhi Day Trip to Taj mahal and Agra Fort by Car</strong></a> is ideal for travelers wanting a memorable tour experience while touring Agra\'s top attractions in one day with minimal travel stress or difficulty!</p>', '[\"Private AC car transfer from Delhi via smooth Yamuna Expressway\",\"visit the magnificent Taj Mahal, one of seven Wonders of the world\",\"Explore Historic Agra Fort, a Mughal royal residence\",\"Professional Tour Guide sharing history and architecture stories\",\"Flexible itinerary with comfortable same-day return to Delhi\",\"Ideal for couples, families, and solo travelers visiting Agra\"]', '[\"Private air-conditioned car for Delhi\\u2013Agra\\u2013Delhi travel\",\"Professional English-speaking tour guide in Agra\",\"Pick-up and drop-off from hotel\\/airport in Delhi\",\"All toll taxes, parking fees, and fuel charges\",\"Sightseeing of Taj Mahal and Agra Fort\",\"Bottled mineral water during the journey\"]', '[\"Entrance fees for Taj Mahal and Agra Fort\",\"Meals and personal expenses\",\"Tips for driver and tour guide\"]', '[{\"title\":\"06:00 AM \\u2013 Pickup from Delhi\",\"points\":[\"Start Your Journey from Delhi Your adventure starts here as we meet and pick you up at your hotel, airport terminal or preferred location in Delhi to start driving along one of India\'s premier highways - Yamuna Expressway - towards Agra for about 3 hours of leisurely touring!\"]},{\"title\":\"09:30 AM \\u2013 Visit Taj Mahal\",\"points\":[\"Arriving in Agra and meeting up with our professional tour guide, commence sightseeing by touring the stunning Taj Mahal - one of UNESCO World Heritage Site and Seven Wonders of the World - which dates back over 700 years ago and admire its exquisite white marble architecture while learning of its romantic history as a part of Emperor Shah Jahan and Mumtaz Mahal\'s story.\"]},{\"title\":\"12:30 PM - Lunch Break\",\"points\":[\"Take time out for yourself during this break to indulge in authentic North Indian cuisine at one of Agra\'s fabulous local restaurants - you are on your own expense, of course! This meal should provide plenty of relaxation.\"]},{\"title\":\"01:30 PM \\u2013 Explore Agra Fort\",\"points\":[\"After lunch, explore Agra Fort, another UNESCO World Heritage Site built by Akbar and serving as his main residence - providing spectacular views of Taj Mahal from its walls!\"]},{\"title\":\"03:00 PM \\u2013 Optional Local Market Visit\",\"points\":[\"Optional Local Market Visit, If time allows, take an optional tour through Agra\'s famed handicraft markets known for marble inlay work, leather goods and traditional souvenirs.\"]},{\"title\":\"04:00 PM \\u2013 Drive Back to Delhi\",\"points\":[\"Begin your comfortable return drive to Delhi via the Yamuna Expressway.\"]},{\"title\":\"07:00 PM \\u2013 Arrival in Delhi\",\"points\":[\"Arrive back into Delhi for your drop-off at your hotel, airport terminal, or preferred location and finish a memorable From Delhi Day Trip to Taj Mahal and Agra Fort by Car!\"]}]', 4999.00, '[\"tours-image\\/cropped_1767538716104_delhi-food-taste.webp\"]', NULL, 20, 1, 'Delhi – Agra', '1 Day', 5.00, 37, '2026-01-07 17:54:28', '2026-04-30 07:56:14', 'From Delhi Day Trip to Taj Mahal and Agra Fort by Car with G', 'Visit the Taj Mahal & Agra Fort on a day trip from Delhi by car with a guide. Enjoy AC travel, skip-the-line entry, expert guide to a seamless experience. Book', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[{\"question\":\"1. How long is the Delhi to Taj Mahal and Agra Fort day trip by car?\",\"answer\":\"The full-day trip usually takes around 10\\u201312 hours, including travel time, sightseeing at the\\nTaj Mahal and Agra Fort, and breaks for meals.\"},{\"question\":\"2. What is included in the Taj Mahal day trip from Delhi?\",\"answer\":\"This tour typically includes a private air-conditioned car, professional tour guide, hotel\\npickup & drop-off, and sightseeing of major attractions in Agra.\"},{\"question\":\"3. Is a guide necessary for visiting the Taj Mahal and Agra Fort?\",\"answer\":\"Yes, a knowledgeable guide enhances your experience by explaining the history,\\narchitecture, and hidden stories of both monuments.\"},{\"question\":\"4. What is the best time to visit the Taj Mahal from Delhi?\",\"answer\":\"The best time is early morning, especially sunrise, to avoid crowds and enjoy beautiful\\nviews of the Taj Mahal.\"},{\"question\":\"5. Can I visit both Taj Mahal and Agra Fort in one day from Delhi?\",\"answer\":\"Yes, both sites are located close to each other in Agra, making it easy to explore them\\ncomfortably in one day trip from Delhi.\"}]', 1, ''),
(50, 'Golden Triangle Tour with Udaipur 7N8D', 'golden-triangle-tour-with-udaipur-7n8d', '<p>The <a href=\"https://indiadaytrip.com/tour/golden-triangle-tour-with-udaipur-7n8d\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>Golden Triangle Tour with Udaipur 7N8D</strong></a> combines North India’s iconic heritage cities with the romantic charm of Udaipur. Along with Delhi, Agra, and Jaipur, this tour includes Udaipur, known for its lakes, palaces, and serene atmosphere. The itinerary offers a balanced mix of history, royal architecture, and scenic beauty. Travelers enjoy comfortable travel, guided sightseeing, and carefully planned stays across multiple destinations. This extended tour is ideal for travelers seeking a deeper exploration of Rajasthan along with classic Golden Triangle highlights.</p>', '[\"Golden Triangle sightseeing\"]', '[\"Private AC transport\"]', '[]', '[{\"title\":\"Day 1\",\"points\":[\"Delhi sightseeing\"]}]', 34999.00, '[\"tours-image\\/cropped_1766858392129_night-delhi.webp\",\"tours-image\\/cropped_1766859100725_night-taj-mahal.webp\",\"tours-image\\/cropped_1766859130236_gatiman.webp\",\"tours-image\\/cropped_1766912391026_gatiman.webp\"]', NULL, 20, 3, 'Delhi – Agra – Jaipur – Udaipur', '8 Days', 5.00, 24, '2026-01-07 17:56:04', '2026-04-30 08:15:40', 'Golden Triangle with Udaipur 7N/8D | Heritage & Royal Tour', 'From the Taj Mahal to Udaipur’s serene lakes, enjoy a perfect blend of heritage, romance & royal charm on this 7N/8D Golden Triangle with Udaipur journey.', '', NULL, 'INDEX,FOLLOW', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '[]', 1, '');
